import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';

const Header = ({ onReset, onPrint, showButtons = false }) => {
  return (
    <header className="py-3 mb-4">
      <div className="container">
        <div className="row align-items-center">
          <div className="col-md-6">
            <div className="d-flex align-items-center">
              <img 
                src="/logoHorizontal.png" 
                alt="Buildu Logo" 
                className="me-3"
                style={{ height: '40px' }}
              />
              <div>
                <h1 className="h3 mb-0 fw-bold"><span style={{ display: 'none' }}>BuildU</span>Sensitivity Analysis </h1>
              </div>
            </div>
          </div>
          <div className="col-md-6 text-md-end">
            <nav className="navbar-nav flex-row justify-content-end">
              <span className="navbar-text text-light">
                Professional Appraisal Analysis
              </span>
            </nav>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;
